-- ──────────────────────────────────────────────────────────────────────────
-- 20260101000000_init.sql
-- ──────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- LifeOS — core schema
-- Every table is owned by a user and protected by row level security.
-- Policies compare against auth.uid(); the client never supplies a user id.
-- ============================================================================

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------- enums ----
create type life_area_key as enum (
  'health','career','money','relationships','family','growth',
  'learning','business','social','travel','hobbies','other'
);
create type priority_level as enum ('low','medium','high');
create type goal_status as enum ('active','paused','completed','archived');
create type task_status as enum ('todo','done','skipped','cancelled');
create type energy_level as enum ('low','medium','high');
create type habit_cadence as enum ('daily','weekly','custom');
create type habit_log_status as enum ('done','skipped','missed');
create type plan_horizon as enum ('month','week');
create type reflection_kind as enum ('daily_reset','weekly_review','journal','life_reset');
create type conversation_kind as enum (
  'general','onboarding','daily_reset','weekly_review','life_reset','planning'
);
create type message_role as enum ('user','assistant','system');
create type memory_kind as enum (
  'preference','routine','constraint','fact','relationship','schedule','value'
);
create type subscription_tier as enum ('free','pro');
create type record_source as enum ('user','ai','import');

-- ------------------------------------------------------------- profiles ----
create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text,
  avatar_url text,
  timezone text not null default 'UTC',
  locale text not null default 'en',
  onboarding_completed boolean not null default false,
  onboarding_completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.user_preferences (
  user_id uuid primary key references auth.users(id) on delete cascade,
  wake_time time not null default '07:00',
  sleep_time time not null default '23:00',
  work_start time not null default '09:00',
  work_end time not null default '18:00',
  working_days smallint[] not null default '{1,2,3,4,5}',        -- 0 = Sunday
  daily_capacity_minutes int not null default 240,
  planning_style text not null default 'balanced',               -- gentle | balanced | ambitious
  ai_tone text not null default 'direct',                        -- warm | direct | coach
  memory_enabled boolean not null default true,
  analytics_enabled boolean not null default true,
  voice_enabled boolean not null default true,
  notifications_enabled boolean not null default true,
  morning_brief_enabled boolean not null default true,
  morning_brief_time time not null default '07:30',
  daily_reset_enabled boolean not null default true,
  daily_reset_time time not null default '21:00',
  task_reminders_enabled boolean not null default true,
  weekly_review_enabled boolean not null default true,
  theme text not null default 'system',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.subscriptions (
  user_id uuid primary key references auth.users(id) on delete cascade,
  tier subscription_tier not null default 'free',
  status text not null default 'active',
  platform text,                                                  -- ios | android | promo
  product_id text,
  started_at timestamptz not null default now(),
  current_period_end timestamptz,
  cancel_at timestamptz,
  updated_at timestamptz not null default now()
);

-- ------------------------------------------------------------ life map ----
create table public.life_areas (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  key life_area_key not null,
  name text not null,
  description text,
  sort_order int not null default 0,
  is_active boolean not null default true,
  satisfaction smallint check (satisfaction between 0 and 100),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, key)
);

-- ---------------------------------------------------------------- goals ----
create table public.goals (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  life_area_id uuid references public.life_areas(id) on delete set null,
  title text not null,
  description text,
  why text,
  target_date date,
  priority priority_level not null default 'medium',
  status goal_status not null default 'active',
  progress smallint not null default 0 check (progress between 0 and 100),
  strategy jsonb not null default '[]'::jsonb,   -- AI-generated ordered steps
  source record_source not null default 'user',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  completed_at timestamptz
);

create table public.goal_milestones (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  goal_id uuid not null references public.goals(id) on delete cascade,
  title text not null,
  due_date date,
  is_done boolean not null default false,
  sort_order int not null default 0,
  completed_at timestamptz,
  created_at timestamptz not null default now()
);

-- ------------------------------------------------------------- projects ----
create table public.projects (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  life_area_id uuid references public.life_areas(id) on delete set null,
  goal_id uuid references public.goals(id) on delete set null,
  title text not null,
  description text,
  status goal_status not null default 'active',
  due_date date,
  progress smallint not null default 0 check (progress between 0 and 100),
  notes text,
  source record_source not null default 'user',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.project_milestones (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  project_id uuid not null references public.projects(id) on delete cascade,
  title text not null,
  due_date date,
  is_done boolean not null default false,
  sort_order int not null default 0,
  completed_at timestamptz,
  created_at timestamptz not null default now()
);

-- --------------------------------------------------------------- habits ----
create table public.habits (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  life_area_id uuid references public.life_areas(id) on delete set null,
  goal_id uuid references public.goals(id) on delete set null,
  title text not null,
  cadence habit_cadence not null default 'daily',
  target_per_week smallint not null default 7 check (target_per_week between 1 and 21),
  days_of_week smallint[],                        -- for custom cadence, 0 = Sunday
  preferred_time time,
  duration_minutes int not null default 20,
  reminder_enabled boolean not null default false,
  is_active boolean not null default true,
  source record_source not null default 'user',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.habit_logs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  habit_id uuid not null references public.habits(id) on delete cascade,
  date date not null,
  status habit_log_status not null default 'done',
  note text,
  created_at timestamptz not null default now(),
  unique (habit_id, date)
);

-- ---------------------------------------------------------------- tasks ----
create table public.tasks (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  life_area_id uuid references public.life_areas(id) on delete set null,
  goal_id uuid references public.goals(id) on delete set null,
  project_id uuid references public.projects(id) on delete set null,
  habit_id uuid references public.habits(id) on delete cascade,
  title text not null,
  notes text,
  scheduled_date date,
  scheduled_time time,
  duration_minutes int not null default 30 check (duration_minutes between 1 and 1440),
  priority priority_level not null default 'medium',
  energy energy_level not null default 'medium',
  status task_status not null default 'todo',
  is_focus boolean not null default false,       -- one of the day's few real priorities
  order_index int not null default 0,
  source record_source not null default 'user',
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ------------------------------------------------------------- calendar ----
create table public.calendar_events (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  life_area_id uuid references public.life_areas(id) on delete set null,
  title text not null,
  notes text,
  location text,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  all_day boolean not null default false,
  -- 'internal' today. External providers land here once an integration ships.
  provider text not null default 'internal',
  external_id text,
  source record_source not null default 'user',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (ends_at >= starts_at)
);

-- ---------------------------------------------------------------- plans ----
create table public.daily_plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  date date not null,
  headline text,                                  -- the contextual line on Home
  summary text,
  focus jsonb not null default '[]'::jsonb,       -- [{task_id,title}] top priorities
  capacity_minutes int,
  planned_minutes int,
  generated_by record_source not null default 'ai',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, date)
);

create table public.weekly_plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  week_start date not null,
  summary text,
  priorities jsonb not null default '[]'::jsonb,
  risks jsonb not null default '[]'::jsonb,       -- detected overload / conflicts
  recommended_moves jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, week_start)
);

create table public.life_plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  title text not null default '90-day plan',
  vision text,
  start_date date not null,
  end_date date not null,
  status goal_status not null default 'active',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.life_plan_items (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  life_plan_id uuid not null references public.life_plans(id) on delete cascade,
  horizon plan_horizon not null,
  position int not null,                          -- month 1..3, week 1..13
  title text not null,
  description text,
  objectives jsonb not null default '[]'::jsonb,
  is_done boolean not null default false,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------- reflections ----
create table public.reflections (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  date date not null default current_date,
  kind reflection_kind not null default 'daily_reset',
  raw_text text,
  mood smallint check (mood between 1 and 5),
  energy smallint check (energy between 1 and 5),
  wins jsonb not null default '[]'::jsonb,
  obstacles jsonb not null default '[]'::jsonb,
  lessons jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now()
);

-- --------------------------------------------------------------- the AI ----
create table public.ai_conversations (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  title text,
  kind conversation_kind not null default 'general',
  archived boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.ai_messages (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  conversation_id uuid not null references public.ai_conversations(id) on delete cascade,
  role message_role not null,
  content text not null default '',
  -- Executed tool calls, each {tool, status, summary, entity_id}. The UI renders these
  -- as receipts, so a claimed action always maps to a stored result.
  actions jsonb not null default '[]'::jsonb,
  suggestions jsonb not null default '[]'::jsonb,
  input_tokens int,
  output_tokens int,
  created_at timestamptz not null default now()
);

create table public.ai_memory (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  kind memory_kind not null default 'fact',
  key text not null,
  value text not null,
  importance smallint not null default 3 check (importance between 1 and 5),
  is_active boolean not null default true,
  source_conversation_id uuid references public.ai_conversations(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, key)
);

-- Daily counter used to enforce the free-tier conversation limit server side.
create table public.ai_usage (
  user_id uuid not null references auth.users(id) on delete cascade,
  date date not null default current_date,
  message_count int not null default 0,
  input_tokens int not null default 0,
  output_tokens int not null default 0,
  primary key (user_id, date)
);

-- ------------------------------------------------- notifications & data ----
create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  kind text not null,                             -- morning_brief | task | habit | overload | reset
  title text not null,
  body text,
  payload jsonb not null default '{}'::jsonb,
  scheduled_for timestamptz,
  delivered_at timestamptz,
  read_at timestamptz,
  local_identifier text,                          -- expo-notifications id, for cancelling
  created_at timestamptz not null default now()
);

create table public.analytics_events (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete cascade,
  name text not null,
  props jsonb not null default '{}'::jsonb,       -- never contains user content
  created_at timestamptz not null default now()
);

-- -------------------------------------------------------------- indexes ----
create index on public.life_areas (user_id, sort_order);
create index on public.goals (user_id, status, target_date);
create index on public.goal_milestones (user_id, goal_id, sort_order);
create index on public.projects (user_id, status);
create index on public.project_milestones (user_id, project_id, sort_order);
create index on public.habits (user_id, is_active);
create index on public.habit_logs (user_id, habit_id, date desc);
create index on public.tasks (user_id, scheduled_date, order_index);
create index on public.tasks (user_id, status, scheduled_date);
create index on public.tasks (user_id, goal_id);
create index on public.tasks (user_id, project_id);
create index on public.calendar_events (user_id, starts_at);
create index on public.daily_plans (user_id, date desc);
create index on public.weekly_plans (user_id, week_start desc);
create index on public.life_plan_items (user_id, life_plan_id, horizon, position);
create index on public.reflections (user_id, date desc);
create index on public.ai_conversations (user_id, updated_at desc);
create index on public.ai_messages (user_id, conversation_id, created_at);
create index on public.ai_memory (user_id, is_active, importance desc);
create index on public.notifications (user_id, scheduled_for);
create index on public.analytics_events (user_id, created_at desc);

-- ──────────────────────────────────────────────────────────────────────────
-- 20260101000100_rls.sql
-- ──────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- Row level security. Default deny; every policy is scoped to auth.uid().
-- Client code never sends a user_id — it is defaulted and enforced here.
-- ============================================================================

-- Default user_id to the authenticated user so a client cannot write another
-- user's rows even if it tries; the WITH CHECK below rejects it regardless.
alter table public.life_areas        alter column user_id set default auth.uid();
alter table public.goals             alter column user_id set default auth.uid();
alter table public.goal_milestones   alter column user_id set default auth.uid();
alter table public.projects          alter column user_id set default auth.uid();
alter table public.project_milestones alter column user_id set default auth.uid();
alter table public.habits            alter column user_id set default auth.uid();
alter table public.habit_logs        alter column user_id set default auth.uid();
alter table public.tasks             alter column user_id set default auth.uid();
alter table public.calendar_events   alter column user_id set default auth.uid();
alter table public.daily_plans       alter column user_id set default auth.uid();
alter table public.weekly_plans      alter column user_id set default auth.uid();
alter table public.life_plans        alter column user_id set default auth.uid();
alter table public.life_plan_items   alter column user_id set default auth.uid();
alter table public.reflections       alter column user_id set default auth.uid();
alter table public.ai_conversations  alter column user_id set default auth.uid();
alter table public.ai_messages       alter column user_id set default auth.uid();
alter table public.ai_memory         alter column user_id set default auth.uid();
alter table public.notifications     alter column user_id set default auth.uid();
alter table public.analytics_events  alter column user_id set default auth.uid();

do $$
declare t text;
begin
  foreach t in array array[
    'profiles','user_preferences','subscriptions','life_areas','goals','goal_milestones',
    'projects','project_milestones','habits','habit_logs','tasks','calendar_events',
    'daily_plans','weekly_plans','life_plans','life_plan_items','reflections',
    'ai_conversations','ai_messages','ai_memory','ai_usage','notifications','analytics_events'
  ]
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force row level security', t);
  end loop;
end $$;

-- profiles / preferences / subscriptions are keyed by the user id itself.
create policy "own profile read"   on public.profiles for select using (auth.uid() = id);
create policy "own profile write"  on public.profiles for update using (auth.uid() = id) with check (auth.uid() = id);
create policy "own profile insert" on public.profiles for insert with check (auth.uid() = id);
create policy "own profile delete" on public.profiles for delete using (auth.uid() = id);

create policy "own prefs" on public.user_preferences for all
  using (auth.uid() = user_id) with check (auth.uid() = user_id);

-- Subscription state is written by verified purchase webhooks (service role),
-- which bypasses RLS; the client may only read it.
create policy "own subscription read" on public.subscriptions for select using (auth.uid() = user_id);

-- ai_usage is a server-side counter: readable by its owner, written by the edge function.
create policy "own usage read" on public.ai_usage for select using (auth.uid() = user_id);

do $$
declare t text;
begin
  foreach t in array array[
    'life_areas','goals','goal_milestones','projects','project_milestones','habits',
    'habit_logs','tasks','calendar_events','daily_plans','weekly_plans','life_plans',
    'life_plan_items','reflections','ai_conversations','ai_messages','ai_memory',
    'notifications','analytics_events'
  ]
  loop
    execute format(
      'create policy "own rows select" on public.%I for select using (auth.uid() = user_id)', t);
    execute format(
      'create policy "own rows insert" on public.%I for insert with check (auth.uid() = user_id)', t);
    execute format(
      'create policy "own rows update" on public.%I for update using (auth.uid() = user_id) with check (auth.uid() = user_id)', t);
    execute format(
      'create policy "own rows delete" on public.%I for delete using (auth.uid() = user_id)', t);
  end loop;
end $$;

-- ──────────────────────────────────────────────────────────────────────────
-- 20260101000200_functions.sql
-- ──────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- Triggers, derived progress, and the RPCs the app calls.
-- ============================================================================

-- ------------------------------------------------------------ updated_at ---
create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array[
    'profiles','user_preferences','subscriptions','life_areas','goals','projects',
    'habits','tasks','calendar_events','daily_plans','weekly_plans','life_plans',
    'ai_conversations','ai_memory'
  ]
  loop
    execute format(
      'create trigger touch_%1$s before update on public.%1$I
         for each row execute function public.touch_updated_at()', t);
  end loop;
end $$;

-- --------------------------------------------------------- new user setup ---
-- A fresh account gets a profile, preferences, a free subscription and the
-- default life areas, so the app never has to special-case an empty account.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, full_name)
  values (new.id, nullif(new.raw_user_meta_data ->> 'full_name', ''))
  on conflict (id) do nothing;

  insert into public.user_preferences (user_id) values (new.id) on conflict do nothing;
  insert into public.subscriptions (user_id) values (new.id) on conflict do nothing;

  insert into public.life_areas (user_id, key, name, sort_order)
  values
    (new.id, 'health',        'Health',          0),
    (new.id, 'career',        'Career',          1),
    (new.id, 'money',         'Money',           2),
    (new.id, 'relationships', 'Relationships',   3),
    (new.id, 'growth',        'Personal growth', 4)
  on conflict (user_id, key) do nothing;

  return new;
end $$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ------------------------------------------------------- derived progress ---
-- A goal's progress is milestone completion when milestones exist; otherwise it
-- is the completion rate of its linked tasks. Keeps the number honest.
create or replace function public.recalc_goal_progress(p_goal_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  total int; done int; pct int;
begin
  select count(*), count(*) filter (where is_done) into total, done
  from public.goal_milestones where goal_id = p_goal_id;

  if total = 0 then
    select count(*), count(*) filter (where status = 'done') into total, done
    from public.tasks where goal_id = p_goal_id;
  end if;

  pct := case when total = 0 then 0 else round((done::numeric / total) * 100) end;
  update public.goals set progress = pct where id = p_goal_id;
end $$;

create or replace function public.recalc_project_progress(p_project_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  total int; done int; pct int;
begin
  select count(*), count(*) filter (where is_done) into total, done
  from public.project_milestones where project_id = p_project_id;

  if total = 0 then
    select count(*), count(*) filter (where status = 'done') into total, done
    from public.tasks where project_id = p_project_id;
  end if;

  pct := case when total = 0 then 0 else round((done::numeric / total) * 100) end;
  update public.projects set progress = pct where id = p_project_id;
end $$;

create or replace function public.on_goal_milestone_change()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.recalc_goal_progress(coalesce(new.goal_id, old.goal_id));
  return coalesce(new, old);
end $$;

create or replace function public.on_project_milestone_change()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.recalc_project_progress(coalesce(new.project_id, old.project_id));
  return coalesce(new, old);
end $$;

create or replace function public.on_task_change()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'done' and (old.status is distinct from 'done') then
    new.completed_at := coalesce(new.completed_at, now());
  elsif new.status <> 'done' then
    new.completed_at := null;
  end if;
  return new;
end $$;

create or replace function public.after_task_change()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if coalesce(new.goal_id, old.goal_id) is not null then
    perform public.recalc_goal_progress(coalesce(new.goal_id, old.goal_id));
  end if;
  if coalesce(new.project_id, old.project_id) is not null then
    perform public.recalc_project_progress(coalesce(new.project_id, old.project_id));
  end if;
  return coalesce(new, old);
end $$;

create trigger goal_milestone_progress
  after insert or update or delete on public.goal_milestones
  for each row execute function public.on_goal_milestone_change();

create trigger project_milestone_progress
  after insert or update or delete on public.project_milestones
  for each row execute function public.on_project_milestone_change();

create trigger task_completed_at
  before update on public.tasks
  for each row execute function public.on_task_change();

create trigger task_rollup
  after insert or update or delete on public.tasks
  for each row execute function public.after_task_change();

-- Completing a goal stamps the time; reopening clears it.
create or replace function public.on_goal_status_change()
returns trigger language plpgsql as $$
begin
  if new.status = 'completed' and old.status is distinct from 'completed' then
    new.completed_at := coalesce(new.completed_at, now());
    new.progress := 100;
  elsif new.status <> 'completed' then
    new.completed_at := null;
  end if;
  return new;
end $$;

create trigger goal_completed_at before update on public.goals
  for each row execute function public.on_goal_status_change();

-- ------------------------------------------------------------ life score ---
-- Per-area progress blends goal progress, habit consistency (last 14 days) and
-- task completion (last 14 days). Only areas with something in them are scored.
create or replace function public.get_life_progress()
returns table (
  life_area_id uuid,
  area_key life_area_key,
  name text,
  goal_progress numeric,
  habit_consistency numeric,
  task_completion numeric,
  score numeric,
  goal_count int,
  habit_count int
)
-- Definer, with every query filtered by auth.uid() below: the function is the
-- boundary, so it does not depend on the caller having rights on the auth schema.
language sql stable security definer set search_path = public, auth as $$
  with areas as (
    select a.id, a.key, a.name from public.life_areas a
    where a.user_id = auth.uid() and a.is_active
  ),
  g as (
    select life_area_id, avg(progress)::numeric as p, count(*)::int as n
    from public.goals
    where user_id = auth.uid() and status = 'active' and life_area_id is not null
    group by life_area_id
  ),
  h as (
    select hb.life_area_id,
           count(*)::int as n,
           coalesce(
             sum(case when hl.status = 'done' then 1 else 0 end)::numeric
             / nullif(sum(hb.target_per_week * 2.0), 0) * 100, 0) as consistency
    from public.habits hb
    left join public.habit_logs hl
      on hl.habit_id = hb.id and hl.date >= current_date - interval '14 days'
    where hb.user_id = auth.uid() and hb.is_active and hb.life_area_id is not null
    group by hb.life_area_id
  ),
  t as (
    select life_area_id,
           count(*) filter (where status = 'done')::numeric / nullif(count(*), 0) * 100 as pct
    from public.tasks
    where user_id = auth.uid()
      and scheduled_date between current_date - interval '14 days' and current_date
      and life_area_id is not null
    group by life_area_id
  )
  select a.id, a.key, a.name,
         round(coalesce(g.p, 0), 1),
         round(least(coalesce(h.consistency, 0), 100), 1),
         round(coalesce(t.pct, 0), 1),
         round(
           ( coalesce(g.p, 0) * case when g.n is null then 0 else 0.5 end
           + least(coalesce(h.consistency, 0), 100) * case when h.n is null then 0 else 0.3 end
           + coalesce(t.pct, 0) * case when t.pct is null then 0 else 0.2 end )
           / nullif(
               ( case when g.n is null then 0 else 0.5 end
               + case when h.n is null then 0 else 0.3 end
               + case when t.pct is null then 0 else 0.2 end ), 0)
         , 1),
         coalesce(g.n, 0), coalesce(h.n, 0)
  from areas a
  left join g on g.life_area_id = a.id
  left join h on h.life_area_id = a.id
  left join t on t.life_area_id = a.id
  order by a.name;
$$;

-- Streak = consecutive days ending today (or yesterday) with a 'done' log.
create or replace function public.get_habit_streak(p_habit_id uuid)
returns int language plpgsql stable security definer set search_path = public, auth as $$
declare
  streak int := 0;
  cursor_date date := current_date;
  has_today boolean;
begin
  select exists (
    select 1 from public.habit_logs
    where habit_id = p_habit_id and user_id = auth.uid()
      and date = current_date and status = 'done'
  ) into has_today;

  if not has_today then cursor_date := current_date - 1; end if;

  loop
    exit when not exists (
      select 1 from public.habit_logs
      where habit_id = p_habit_id and user_id = auth.uid()
        and date = cursor_date and status = 'done'
    );
    streak := streak + 1;
    cursor_date := cursor_date - 1;
  end loop;

  return streak;
end $$;

-- --------------------------------------------------------- privacy tools ---
-- Full export of everything we hold about the caller.
create or replace function public.export_my_data()
returns jsonb language sql stable security definer set search_path = public, auth as $$
  select jsonb_build_object(
    'exported_at', now(),
    'profile',        (select to_jsonb(p) from public.profiles p where p.id = auth.uid()),
    'preferences',    (select to_jsonb(x) from public.user_preferences x where x.user_id = auth.uid()),
    'life_areas',     coalesce((select jsonb_agg(to_jsonb(x)) from public.life_areas x where x.user_id = auth.uid()), '[]'::jsonb),
    'goals',          coalesce((select jsonb_agg(to_jsonb(x)) from public.goals x where x.user_id = auth.uid()), '[]'::jsonb),
    'goal_milestones',coalesce((select jsonb_agg(to_jsonb(x)) from public.goal_milestones x where x.user_id = auth.uid()), '[]'::jsonb),
    'projects',       coalesce((select jsonb_agg(to_jsonb(x)) from public.projects x where x.user_id = auth.uid()), '[]'::jsonb),
    'habits',         coalesce((select jsonb_agg(to_jsonb(x)) from public.habits x where x.user_id = auth.uid()), '[]'::jsonb),
    'habit_logs',     coalesce((select jsonb_agg(to_jsonb(x)) from public.habit_logs x where x.user_id = auth.uid()), '[]'::jsonb),
    'tasks',          coalesce((select jsonb_agg(to_jsonb(x)) from public.tasks x where x.user_id = auth.uid()), '[]'::jsonb),
    'calendar_events',coalesce((select jsonb_agg(to_jsonb(x)) from public.calendar_events x where x.user_id = auth.uid()), '[]'::jsonb),
    'daily_plans',    coalesce((select jsonb_agg(to_jsonb(x)) from public.daily_plans x where x.user_id = auth.uid()), '[]'::jsonb),
    'weekly_plans',   coalesce((select jsonb_agg(to_jsonb(x)) from public.weekly_plans x where x.user_id = auth.uid()), '[]'::jsonb),
    'life_plans',     coalesce((select jsonb_agg(to_jsonb(x)) from public.life_plans x where x.user_id = auth.uid()), '[]'::jsonb),
    'reflections',    coalesce((select jsonb_agg(to_jsonb(x)) from public.reflections x where x.user_id = auth.uid()), '[]'::jsonb),
    'conversations',  coalesce((select jsonb_agg(to_jsonb(x)) from public.ai_conversations x where x.user_id = auth.uid()), '[]'::jsonb),
    'messages',       coalesce((select jsonb_agg(to_jsonb(x)) from public.ai_messages x where x.user_id = auth.uid()), '[]'::jsonb),
    'memory',         coalesce((select jsonb_agg(to_jsonb(x)) from public.ai_memory x where x.user_id = auth.uid()), '[]'::jsonb)
  );
$$;

-- Deletes the auth user; every table cascades from it.
create or replace function public.delete_my_account()
returns void language plpgsql security definer set search_path = public, auth as $$
declare uid uuid := auth.uid();
begin
  if uid is null then raise exception 'not authenticated'; end if;
  delete from auth.users where id = uid;
end $$;

-- Wipes conversations and memory without deleting the account.
create or replace function public.forget_everything()
returns void language plpgsql security definer set search_path = public, auth as $$
begin
  delete from public.ai_messages where user_id = auth.uid();
  delete from public.ai_conversations where user_id = auth.uid();
  delete from public.ai_memory where user_id = auth.uid();
end $$;

revoke all on function public.delete_my_account() from public;
grant execute on function public.delete_my_account() to authenticated;
grant execute on function public.export_my_data() to authenticated;
grant execute on function public.forget_everything() to authenticated;
grant execute on function public.get_life_progress() to authenticated;
grant execute on function public.get_habit_streak(uuid) to authenticated;

-- Server-owned usage counter used to enforce the free-tier conversation limit.
create or replace function public.increment_ai_usage(
  p_user uuid, p_date date, p_input int default 0, p_output int default 0
) returns void language plpgsql security definer set search_path = public as $$
begin
  insert into public.ai_usage (user_id, date, message_count, input_tokens, output_tokens)
  values (p_user, p_date, 1, coalesce(p_input, 0), coalesce(p_output, 0))
  on conflict (user_id, date) do update
    set message_count = public.ai_usage.message_count + 1,
        input_tokens  = public.ai_usage.input_tokens + coalesce(p_input, 0),
        output_tokens = public.ai_usage.output_tokens + coalesce(p_output, 0);
end $$;

revoke all on function public.increment_ai_usage(uuid, date, int, int) from public;

-- ──────────────────────────────────────────────────────────────────────────
-- 20260101000300_subscriptions.sql
-- ──────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- Tiered subscriptions, metered AI usage, and remotely configurable pricing.
--
-- Tiers and statuses are text with a check constraint rather than enums, so a new
-- plan (or a pricing experiment) never needs a schema migration.
-- ============================================================================

-- ------------------------------------------------------- runtime configuration --
-- Overrides merged on top of the compiled catalogue in _shared/plans.ts. Prices,
-- quotas, entitlements and model routing can all be changed here without a release.
create table public.app_config (
  key text primary key,
  value jsonb not null default '{}'::jsonb,
  -- Public rows are readable by any signed-in user (plans, pricing). Anything
  -- operational stays private to the service role.
  is_public boolean not null default false,
  updated_at timestamptz not null default now()
);

alter table public.app_config enable row level security;
alter table public.app_config force row level security;

create policy "public config is readable" on public.app_config
  for select using (is_public);

insert into public.app_config (key, value, is_public)
values ('plans', '{}'::jsonb, true)
on conflict (key) do nothing;

create trigger touch_app_config before update on public.app_config
  for each row execute function public.touch_updated_at();

-- ------------------------------------------------------------- subscriptions --
alter table public.subscriptions
  alter column tier drop default,
  alter column tier type text using tier::text,
  alter column tier set default 'free';

alter table public.subscriptions
  add constraint subscriptions_tier_check
  check (tier in ('free', 'plus', 'pro', 'ultra'));

alter table public.subscriptions
  alter column status set default 'free';

update public.subscriptions set status = 'free' where tier = 'free';

alter table public.subscriptions
  add constraint subscriptions_status_check
  check (status in ('free', 'trialing', 'active', 'grace_period', 'canceled', 'expired'));

alter table public.subscriptions
  add column if not exists current_period_start timestamptz,
  add column if not exists trial_ends_at timestamptz,
  add column if not exists grace_until timestamptz,
  add column if not exists canceled_at timestamptz,
  add column if not exists will_renew boolean not null default false,
  add column if not exists provider text not null default 'none',
  add column if not exists store_transaction_id text,
  add column if not exists store_original_transaction_id text,
  add column if not exists last_verified_at timestamptz;

alter table public.subscriptions
  add constraint subscriptions_provider_check
  check (provider in ('none', 'apple', 'google', 'promo'));

-- One store transaction belongs to one account.
create unique index if not exists subscriptions_original_transaction_idx
  on public.subscriptions (store_original_transaction_id)
  where store_original_transaction_id is not null;

-- The old daily counter is replaced by period-based metering below.
drop function if exists public.increment_ai_usage(uuid, date, int, int);
drop table if exists public.ai_usage;

-- ---------------------------------------------------------------- metering --
-- One row per user, period and meter. Written only by the edge functions through
-- consume_usage(), so a device cannot reset its own allowance.
create table public.usage_counters (
  user_id uuid not null references auth.users(id) on delete cascade,
  period_start date not null,
  meter text not null,
  used numeric not null default 0,
  updated_at timestamptz not null default now(),
  primary key (user_id, period_start, meter),
  constraint usage_counters_meter_check check (meter in (
    'ai_requests', 'advanced_requests', 'voice_seconds', 'life_resets',
    'planning_requests', 'memory_items', 'agent_runs'
  ))
);

-- The ledger behind the counters: what was spent, on what, and when.
create table public.usage_events (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  period_start date not null,
  meter text not null,
  amount numeric not null,
  operation text not null,
  tier text,
  model text,
  created_at timestamptz not null default now()
);

create index on public.usage_events (user_id, created_at desc);
create index on public.usage_counters (user_id, period_start);

alter table public.usage_counters enable row level security;
alter table public.usage_counters force row level security;
alter table public.usage_events enable row level security;
alter table public.usage_events force row level security;

-- Readable by their owner; writable only by the service role (which bypasses RLS).
create policy "own usage counters" on public.usage_counters
  for select using (auth.uid() = user_id);
create policy "own usage events" on public.usage_events
  for select using (auth.uid() = user_id);

-- ----------------------------------------------------------------- functions --
/*
  Atomically checks an allowance and spends it.

  The limit is supplied by the caller because plan configuration lives in the
  catalogue, not in the database — but the check and the increment happen together
  here, so two concurrent requests cannot both slip past the last unit.
*/
create or replace function public.consume_usage(
  p_user uuid,
  p_period_start date,
  p_meter text,
  p_amount numeric,
  p_limit numeric,
  p_operation text default 'unknown',
  p_tier text default null,
  p_model text default null
) returns table (allowed boolean, used numeric, remaining numeric)
language plpgsql security definer set search_path = public as $$
declare
  v_used numeric;
begin
  insert into public.usage_counters (user_id, period_start, meter, used)
  values (p_user, p_period_start, p_meter, 0)
  on conflict (user_id, period_start, meter) do nothing;

  select uc.used into v_used
  from public.usage_counters uc
  where uc.user_id = p_user and uc.period_start = p_period_start and uc.meter = p_meter
  for update;

  if v_used + p_amount > p_limit then
    return query select false, v_used, greatest(p_limit - v_used, 0);
    return;
  end if;

  update public.usage_counters uc
     set used = uc.used + p_amount, updated_at = now()
   where uc.user_id = p_user and uc.period_start = p_period_start and uc.meter = p_meter
  returning uc.used into v_used;

  insert into public.usage_events (user_id, period_start, meter, amount, operation, tier, model)
  values (p_user, p_period_start, p_meter, p_amount, p_operation, p_tier, p_model);

  return query select true, v_used, greatest(p_limit - v_used, 0);
end $$;

/* Releases usage when an operation failed after being charged. */
create or replace function public.refund_usage(
  p_user uuid,
  p_period_start date,
  p_meter text,
  p_amount numeric
) returns void language plpgsql security definer set search_path = public as $$
begin
  update public.usage_counters
     set used = greatest(used - p_amount, 0), updated_at = now()
   where user_id = p_user and period_start = p_period_start and meter = p_meter;
end $$;

/* What the user has spent this period — the numbers behind the usage screen. */
create or replace function public.get_usage_summary(p_period_start date)
returns table (meter text, used numeric)
language sql stable security definer set search_path = public, auth as $$
  select uc.meter, uc.used
  from public.usage_counters uc
  where uc.user_id = auth.uid() and uc.period_start = p_period_start;
$$;

revoke all on function public.consume_usage(uuid, date, text, numeric, numeric, text, text, text) from public;
revoke all on function public.refund_usage(uuid, date, text, numeric) from public;
grant execute on function public.get_usage_summary(date) to authenticated;

-- New accounts start on Free with no store relationship.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, full_name)
  values (new.id, nullif(new.raw_user_meta_data ->> 'full_name', ''))
  on conflict (id) do nothing;

  insert into public.user_preferences (user_id) values (new.id) on conflict do nothing;

  insert into public.subscriptions (user_id, tier, status)
  values (new.id, 'free', 'free')
  on conflict do nothing;

  insert into public.life_areas (user_id, key, name, sort_order)
  values
    (new.id, 'health',        'Health',          0),
    (new.id, 'career',        'Career',          1),
    (new.id, 'money',         'Money',           2),
    (new.id, 'relationships', 'Relationships',   3),
    (new.id, 'growth',        'Personal growth', 4)
  on conflict (user_id, key) do nothing;

  return new;
end $$;

-- ──────────────────────────────────────────────────────────────────────────
-- 20260101000400_agents_insights.sql
-- ──────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- What the assistant leaves behind: agent runs, deep analyses and weekly
-- reviews as durable reports, plus the proactive insights the app surfaces.
-- ============================================================================

-- Reports outlive the conversation that produced them, so a deep analysis or an
-- agent run can be read back weeks later without scrolling a chat.
create table public.ai_reports (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  kind text not null check (kind in ('deep_analysis', 'agent_run', 'weekly_review')),
  agent_key text,
  title text not null,
  body text not null,
  -- The receipts for whatever the run actually changed.
  actions jsonb not null default '[]'::jsonb,
  conversation_id uuid references public.ai_conversations(id) on delete set null,
  created_at timestamptz not null default now()
);

/*
  Proactive observations. Detection runs on the device from data already loaded, so
  everyone gets it instantly and offline; rows are stored only when the user's plan
  includes proactive notifications, so there is something to schedule from.
*/
create table public.insights (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  kind text not null,
  title text not null,
  body text,
  severity text not null default 'info' check (severity in ('info', 'attention', 'urgent')),
  entity_type text,
  entity_id uuid,
  status text not null default 'new' check (status in ('new', 'seen', 'dismissed', 'acted')),
  -- The same observation should not be raised twice in a day.
  fingerprint text not null,
  valid_until date,
  created_at timestamptz not null default now(),
  unique (user_id, fingerprint)
);

create index on public.ai_reports (user_id, created_at desc);
create index on public.insights (user_id, status, created_at desc);

alter table public.ai_reports enable row level security;
alter table public.ai_reports force row level security;
alter table public.insights enable row level security;
alter table public.insights force row level security;

alter table public.ai_reports alter column user_id set default auth.uid();
alter table public.insights   alter column user_id set default auth.uid();

do $$
declare t text;
begin
  foreach t in array array['ai_reports', 'insights']
  loop
    execute format(
      'create policy "own rows select" on public.%I for select using (auth.uid() = user_id)', t);
    execute format(
      'create policy "own rows insert" on public.%I for insert with check (auth.uid() = user_id)', t);
    execute format(
      'create policy "own rows update" on public.%I for update using (auth.uid() = user_id) with check (auth.uid() = user_id)', t);
    execute format(
      'create policy "own rows delete" on public.%I for delete using (auth.uid() = user_id)', t);
  end loop;
end $$;

-- Reports and insights are part of the export and of "forget everything".
create or replace function public.forget_everything()
returns void language plpgsql security definer set search_path = public, auth as $$
begin
  delete from public.ai_messages where user_id = auth.uid();
  delete from public.ai_conversations where user_id = auth.uid();
  delete from public.ai_memory where user_id = auth.uid();
  delete from public.ai_reports where user_id = auth.uid();
  delete from public.insights where user_id = auth.uid();
end $$;

create or replace function public.export_my_data()
returns jsonb language sql stable security definer set search_path = public, auth as $$
  select jsonb_build_object(
    'exported_at', now(),
    'profile',        (select to_jsonb(p) from public.profiles p where p.id = auth.uid()),
    'preferences',    (select to_jsonb(x) from public.user_preferences x where x.user_id = auth.uid()),
    'subscription',   (select to_jsonb(x) from public.subscriptions x where x.user_id = auth.uid()),
    'life_areas',     coalesce((select jsonb_agg(to_jsonb(x)) from public.life_areas x where x.user_id = auth.uid()), '[]'::jsonb),
    'goals',          coalesce((select jsonb_agg(to_jsonb(x)) from public.goals x where x.user_id = auth.uid()), '[]'::jsonb),
    'goal_milestones',coalesce((select jsonb_agg(to_jsonb(x)) from public.goal_milestones x where x.user_id = auth.uid()), '[]'::jsonb),
    'projects',       coalesce((select jsonb_agg(to_jsonb(x)) from public.projects x where x.user_id = auth.uid()), '[]'::jsonb),
    'habits',         coalesce((select jsonb_agg(to_jsonb(x)) from public.habits x where x.user_id = auth.uid()), '[]'::jsonb),
    'habit_logs',     coalesce((select jsonb_agg(to_jsonb(x)) from public.habit_logs x where x.user_id = auth.uid()), '[]'::jsonb),
    'tasks',          coalesce((select jsonb_agg(to_jsonb(x)) from public.tasks x where x.user_id = auth.uid()), '[]'::jsonb),
    'calendar_events',coalesce((select jsonb_agg(to_jsonb(x)) from public.calendar_events x where x.user_id = auth.uid()), '[]'::jsonb),
    'daily_plans',    coalesce((select jsonb_agg(to_jsonb(x)) from public.daily_plans x where x.user_id = auth.uid()), '[]'::jsonb),
    'weekly_plans',   coalesce((select jsonb_agg(to_jsonb(x)) from public.weekly_plans x where x.user_id = auth.uid()), '[]'::jsonb),
    'life_plans',     coalesce((select jsonb_agg(to_jsonb(x)) from public.life_plans x where x.user_id = auth.uid()), '[]'::jsonb),
    'reflections',    coalesce((select jsonb_agg(to_jsonb(x)) from public.reflections x where x.user_id = auth.uid()), '[]'::jsonb),
    'reports',        coalesce((select jsonb_agg(to_jsonb(x)) from public.ai_reports x where x.user_id = auth.uid()), '[]'::jsonb),
    'insights',       coalesce((select jsonb_agg(to_jsonb(x)) from public.insights x where x.user_id = auth.uid()), '[]'::jsonb),
    'conversations',  coalesce((select jsonb_agg(to_jsonb(x)) from public.ai_conversations x where x.user_id = auth.uid()), '[]'::jsonb),
    'messages',       coalesce((select jsonb_agg(to_jsonb(x)) from public.ai_messages x where x.user_id = auth.uid()), '[]'::jsonb),
    'memory',         coalesce((select jsonb_agg(to_jsonb(x)) from public.ai_memory x where x.user_id = auth.uid()), '[]'::jsonb),
    'usage',          coalesce((select jsonb_agg(to_jsonb(x)) from public.usage_counters x where x.user_id = auth.uid()), '[]'::jsonb)
  );
$$;

-- ──────────────────────────────────────────────────────────────────────────
-- 20260101000500_store_events.sql
-- ──────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- Store event ledger and rate limiting.
--
-- Every purchase verification and every store notification is recorded here with
-- the store's own identifier, so a replayed webhook or a re-sent receipt updates
-- the same row instead of creating a second entitlement.
-- ============================================================================

create table public.store_events (
  id uuid primary key default gen_random_uuid(),
  provider text not null check (provider in ('apple', 'google')),
  -- The store's identifier for this event: Apple's notificationUUID or transactionId,
  -- Google's messageId or purchaseToken+eventTime. Unique per provider.
  event_id text not null,
  kind text not null,
  user_id uuid references auth.users(id) on delete set null,
  original_transaction_id text,
  product_id text,
  payload jsonb not null default '{}'::jsonb,
  status text not null default 'processed' check (status in ('processed', 'ignored', 'failed')),
  error text,
  created_at timestamptz not null default now(),
  unique (provider, event_id)
);

create index on public.store_events (original_transaction_id, created_at desc);
create index on public.store_events (user_id, created_at desc);

alter table public.store_events enable row level security;
alter table public.store_events force row level security;

-- Written only by the service role in the verification and notification functions.
-- A user may read their own history; nobody may write from a device.
create policy "own store events" on public.store_events
  for select using (auth.uid() = user_id);

/*
  A cheap per-user, per-action rate limit for the edge functions. This is abuse
  protection in front of the usage meter, not a replacement for it: it stops a client
  hammering an endpoint even when it has allowance left.
*/
create table public.rate_limits (
  user_id uuid not null references auth.users(id) on delete cascade,
  action text not null,
  window_start timestamptz not null,
  count int not null default 0,
  primary key (user_id, action, window_start)
);

alter table public.rate_limits enable row level security;
alter table public.rate_limits force row level security;

create or replace function public.check_rate_limit(
  p_user uuid,
  p_action text,
  p_limit int,
  p_window_seconds int
) returns table (allowed boolean, retry_after_seconds int)
language plpgsql security definer set search_path = public as $$
declare
  v_window timestamptz := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  v_count int;
begin
  insert into public.rate_limits (user_id, action, window_start, count)
  values (p_user, p_action, v_window, 1)
  on conflict (user_id, action, window_start)
    do update set count = public.rate_limits.count + 1
  returning count into v_count;

  -- Keep the table small; old windows are of no interest.
  delete from public.rate_limits
   where user_id = p_user and window_start < now() - make_interval(secs => p_window_seconds * 4);

  if v_count > p_limit then
    return query select false,
      greatest(1, p_window_seconds - floor(extract(epoch from now() - v_window))::int);
    -- Stop here: falling through would append a contradictory "allowed" row.
    return;
  end if;

  return query select true, 0;
end $$;

revoke all on function public.check_rate_limit(uuid, text, int, int) from public;

/*
  Applies a verified store subscription to an account, idempotently.

  The event id is recorded first; a replay hits the unique constraint, is reported as
  a duplicate, and changes nothing. Entitlement is only ever written here or by the
  same path in the verification function — never from a device.
*/
create or replace function public.apply_store_subscription(
  p_provider text,
  p_event_id text,
  p_kind text,
  p_user uuid,
  p_tier text,
  p_status text,
  p_product_id text,
  p_original_transaction_id text,
  p_transaction_id text,
  p_period_start timestamptz,
  p_period_end timestamptz,
  p_trial_ends_at timestamptz,
  p_grace_until timestamptz,
  p_will_renew boolean,
  p_payload jsonb default '{}'::jsonb
) returns table (applied boolean, duplicate boolean)
language plpgsql security definer set search_path = public as $$
declare
  -- GET DIAGNOSTICS yields an integer row count; keeping the type honest avoids
  -- relying on an implicit cast.
  v_inserted int := 0;
begin
  insert into public.store_events (
    provider, event_id, kind, user_id, original_transaction_id, product_id, payload
  )
  values (
    p_provider, p_event_id, p_kind, p_user, p_original_transaction_id, p_product_id, p_payload
  )
  on conflict (provider, event_id) do nothing;

  get diagnostics v_inserted = row_count;

  if v_inserted = 0 then
    -- Already handled: a duplicate notification or a re-sent receipt. Returning here
    -- is what makes this idempotent — without it a replayed event would fall through
    -- and rewrite the subscription, which can downgrade a paying account.
    return query select false, true;
    return;
  end if;

  update public.subscriptions
     set tier = p_tier,
         status = p_status,
         platform = p_provider,
         provider = p_provider,
         product_id = p_product_id,
         current_period_start = p_period_start,
         current_period_end = p_period_end,
         trial_ends_at = p_trial_ends_at,
         grace_until = p_grace_until,
         canceled_at = case when p_status = 'canceled' then now() else null end,
         will_renew = coalesce(p_will_renew, false),
         store_transaction_id = p_transaction_id,
         store_original_transaction_id = p_original_transaction_id,
         last_verified_at = now(),
         updated_at = now()
   where user_id = p_user;

  return query select true, false;
end $$;

revoke all on function public.apply_store_subscription(
  text, text, text, uuid, text, text, text, text, text,
  timestamptz, timestamptz, timestamptz, timestamptz, boolean, jsonb
) from public;

/* Finds the account a store subscription already belongs to. */
create or replace function public.user_for_original_transaction(p_original_transaction_id text)
returns uuid language sql stable security definer set search_path = public as $$
  select user_id from public.subscriptions
   where store_original_transaction_id = p_original_transaction_id
   limit 1;
$$;

revoke all on function public.user_for_original_transaction(text) from public;

-- ──────────────────────────────────────────────────────────────────────────
-- 20260101000600_ai_router.sql
-- ──────────────────────────────────────────────────────────────────────────
-- AI router: request accounting, monetary budgets and provider health.
--
-- Additive only. Nothing here alters an existing table, policy or function, so the
-- verified schema keeps working exactly as it did while the new path is being proven.

-- ─────────────────────────────────────────────────────── request accounting ──
-- One row per model call, successful or not. This is what makes an AI bill
-- explainable: which provider answered, what it cost, and whether that cost was
-- measured or estimated.
create table public.ai_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  request_id text not null,
  tier text not null,
  task_type text not null,
  provider text not null,
  model text not null,
  input_tokens int not null default 0,
  output_tokens int not null default 0,
  cached_tokens int not null default 0,
  estimated_cost numeric(12, 8) not null default 0,
  actual_cost numeric(12, 8) not null default 0,
  -- 'metered' when the provider reported usage we priced; 'estimated' when it did not.
  -- Never conflate the two: margin reporting depends on knowing which is which.
  accounting_method text not null default 'estimated'
    check (accounting_method in ('metered', 'estimated')),
  latency_ms int not null default 0,
  success boolean not null default true,
  error_code text,
  fallback_used boolean not null default false,
  fallback_reason text,
  created_at timestamptz not null default now()
);

create index on public.ai_requests (user_id, created_at desc);
create index on public.ai_requests (request_id);
create index on public.ai_requests (provider, model, created_at desc);

-- ────────────────────────────────────────────────────────── budget ledger ──
-- The running monetary total per user per period, alongside the operation allowance
-- in usage_counters. Two different questions, two different limits.
create table public.ai_budgets (
  user_id uuid not null references auth.users(id) on delete cascade,
  period_start date not null,
  -- Reserved before a call, released after. Never negative.
  reserved numeric(12, 8) not null default 0 check (reserved >= 0),
  -- Settled cost of completed calls.
  spent numeric(12, 8) not null default 0 check (spent >= 0),
  ceiling numeric(12, 8) not null,
  updated_at timestamptz not null default now(),
  primary key (user_id, period_start)
);

-- Outstanding holds. A row exists only between reservation and settlement, so an
-- orphaned row is a crashed request and can be swept.
create table public.ai_budget_reservations (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  period_start date not null,
  request_id text not null,
  amount numeric(12, 8) not null check (amount >= 0),
  created_at timestamptz not null default now(),
  -- One hold per request id. A retried request cannot reserve twice.
  unique (user_id, request_id)
);

create index on public.ai_budget_reservations (created_at);

-- ───────────────────────────────────────────────────────── provider health ──
create table public.ai_provider_health (
  key text primary key,
  provider text not null,
  model text,
  successes bigint not null default 0,
  failures bigint not null default 0,
  consecutive_failures int not null default 0,
  state text not null default 'closed' check (state in ('closed', 'open', 'half_open')),
  opened_at timestamptz,
  last_failure_at timestamptz,
  updated_at timestamptz not null default now()
);

-- ───────────────────────────────────────────────────────────────────── RLS ──
alter table public.ai_requests enable row level security;
alter table public.ai_requests force row level security;
alter table public.ai_budgets enable row level security;
alter table public.ai_budgets force row level security;
alter table public.ai_budget_reservations enable row level security;
alter table public.ai_budget_reservations force row level security;
alter table public.ai_provider_health enable row level security;
alter table public.ai_provider_health force row level security;

-- A user may read their own AI history and budget. Nobody writes through the API:
-- every write goes through a definer function called with the service role, so a
-- client cannot grant itself budget by inserting a row.
create policy "own ai requests" on public.ai_requests
  for select using (auth.uid() = user_id);

create policy "own ai budget" on public.ai_budgets
  for select using (auth.uid() = user_id);

-- No policy at all on ai_budget_reservations or ai_provider_health: with RLS forced
-- and no policy, they are invisible to anon and authenticated by construction.

grant select on public.ai_requests to authenticated;
grant select on public.ai_budgets to authenticated;

-- ────────────────────────────────────────────── concurrency-safe reservation ──
-- The race this exists to lose safely: a user has $0.10 left and two requests arrive
-- at once, each estimated at $0.08. Both read "enough left" and both proceed, and the
-- budget is overspent by 60%.
--
-- The insert into ai_budgets takes a row lock for the rest of the transaction, so the
-- second caller blocks until the first has committed its reservation and then reads
-- the updated total. One succeeds, one is refused.
create or replace function public.reserve_ai_budget(
  p_user uuid,
  p_period_start date,
  p_request_id text,
  p_amount numeric,
  p_ceiling numeric
)
returns table (allowed boolean, remaining numeric, reason text)
language plpgsql security definer set search_path = public, auth as $$
declare
  v_reserved numeric;
  v_spent numeric;
  v_remaining numeric;
begin
  -- Establish the row, then lock it. `on conflict do update` on a no-op keeps the
  -- lock semantics identical whether or not the row already existed.
  insert into public.ai_budgets (user_id, period_start, ceiling)
  values (p_user, p_period_start, p_ceiling)
  on conflict (user_id, period_start)
    do update set ceiling = excluded.ceiling, updated_at = now();

  select reserved, spent into v_reserved, v_spent
  from public.ai_budgets
  where user_id = p_user and period_start = p_period_start
  for update;

  v_remaining := p_ceiling - v_spent - v_reserved;

  if p_amount > v_remaining then
    return query select false, greatest(0, v_remaining), 'budget_exceeded'::text;
    -- Stop here. Falling through would append a contradictory "allowed" row.
    return;
  end if;

  insert into public.ai_budget_reservations (user_id, period_start, request_id, amount)
  values (p_user, p_period_start, p_request_id, p_amount)
  on conflict (user_id, request_id) do nothing;

  update public.ai_budgets
     set reserved = reserved + p_amount, updated_at = now()
   where user_id = p_user and period_start = p_period_start;

  return query select true, v_remaining - p_amount, null::text;
end $$;

-- Converts a hold into settled spend. Called with the real cost once the provider has
-- answered; an amount of 0 simply releases the hold, which is what a failed call does.
create or replace function public.settle_ai_budget(
  p_user uuid,
  p_period_start date,
  p_request_id text,
  p_actual numeric
)
-- The OUT column is named total_spent, not spent: an OUT parameter sharing a name
-- with a column of the table being updated makes every unqualified reference to it
-- ambiguous, and PostgreSQL rejects the function at run time rather than at creation.
returns table (settled boolean, total_spent numeric)
language plpgsql security definer set search_path = public, auth as $$
declare
  v_reserved numeric;
  v_spent numeric;
begin
  delete from public.ai_budget_reservations
   where user_id = p_user and request_id = p_request_id
  returning amount into v_reserved;

  if v_reserved is null then
    -- Nothing held: either already settled or never reserved. Report the current total
    -- rather than double-charging.
    select b.spent into v_spent from public.ai_budgets b
     where b.user_id = p_user and b.period_start = p_period_start;
    return query select false, coalesce(v_spent, 0::numeric);
    return;
  end if;

  update public.ai_budgets b
     set reserved = greatest(0, b.reserved - v_reserved),
         spent = b.spent + greatest(0, p_actual),
         updated_at = now()
   where b.user_id = p_user and b.period_start = p_period_start
  returning b.spent into v_spent;

  return query select true, coalesce(v_spent, 0::numeric);
end $$;

-- Reads the caller's own budget. Definer because it touches auth.uid().
create or replace function public.get_ai_budget(p_period_start date)
returns table (spent numeric, reserved numeric, ceiling numeric)
language sql stable security definer set search_path = public, auth as $$
  select b.spent, b.reserved, b.ceiling
    from public.ai_budgets b
   where b.user_id = auth.uid() and b.period_start = p_period_start;
$$;

-- Only the service role may move money. `public` includes anon and authenticated.
revoke all on function public.reserve_ai_budget(uuid, date, text, numeric, numeric) from public;
revoke all on function public.settle_ai_budget(uuid, date, text, numeric) from public;
grant execute on function public.get_ai_budget(date) to authenticated;
